(7726701, 1272061, 114285, '<td valign="top">Incredibly cute scene, Im not sure if it really  fits the challenge, since they look pretty  static to me, also lacks sharpness.</td>', 'Incredibly cute scene, Im not sure if it really  fits the challenge, since they look pretty  static to me, also lacks sharpness.', '2022-08-10 08:43:00.000000', NULL, 1),
(7726702, 1272075, 114285, '<td valign="top">I wouldve cropped it tighter, not a fan of the dark space up top. I love the vivid colours though.</td>', 'I wouldve cropped it tighter, not a fan of the dark space up top. I love the vivid colours though.', '2022-08-10 08:45:02.000000', NULL, 1),
(7726703, 1272195, 114285, '<td valign="top">So pretty, love the light.</td>', 'So pretty, love the light.', '2022-08-10 08:45:32.000000', NULL, 1),
(7726705, 1272205, 114285, '<td valign="top">I love the wingspan, just lacks sharpness somewhat.<br/> <br/>Did you think about cloning the distracting log, just a thought :)</td>', 'I love the wingspan, just lacks sharpness somewhat. Did you think about cloning the distracting log, just a thought :)', '2022-08-10 09:42:50.000000', NULL, 1),
(7726792, 1272211, 65234, '<td valign="top">The passing people almost look like cartoons.</td>', 'The passing people almost look like cartoons.', '2022-08-10 16:18:16.000000', NULL, 1),
(7726795, 1272195, 65234, '<td valign="top">Pretty light.</td>', 'Pretty light.', '2022-08-10 16:19:20.000000', NULL, 1),
(7726800, 1272022, 65234, '<td valign="top">My fave in the challenge. Crisp stop-action with a pleasing OOF background. I might have cropped to put the bird on the lower left rule of thirds intersection, just to give him more space to fly into, but then I rarely go for centered compositions. Personal quirk.</td>', 'My fave in the challenge. Crisp stop-action with a pleasing OOF background. I might have cropped to put the bird on the lower left rule of thirds intersection, just to give him more space to fly into, but then I rarely go for centered compositions. Personal quirk.', '2022-08-10 16:24:50.000000', NULL, 1),
(7726801, 1272206, 65234, '<td valign="top">Love how the splash looks so three-dimensional. Almost like it''s solid. Clever image.</td>', 'Love how the splash looks so three-dimensional. Almost like it''s solid. Clever image.', '2022-08-10 16:26:14.000000', NULL, 1),
